      "id": "plan.repeat_program",
      "tiers": [
        {
          "id": "plan.repeat_program:t1",
          "title": "Знакомый поворот",
          "phrase": "Ты выполнил одну и ту же версию программы в 3 разных дня. Карта знакомая, а каждая отметка — новая история.",
          "imagePrompt": "A small tortoise with a canvas satchel unrolls a route map beside an arched trail gate. Three footprint-shaped paving stones mark separate arrivals, and the tortoise happily recognizes the bend drawn on its map.",
          "fishMarkup": "[warm]Ты выполнил одну и ту же версию программы в <emphasis>3 разных дня</emphasis>. [playful]Карта знакомая, а каждая отметка — новая история.",
          "audioText": "Ты выполнил одну и ту же версию программы в 3 разных дня. Карта знакомая, а каждая отметка — новая история."
        },
        {
          "id": "plan.repeat_program:t2",
          "title": "Свой на маршруте",
          "phrase": "Одна и та же версия программы выполнена в 8 разных дней — ты возвращаешься к знакомому маршруту. Карта уже встречает тебя как своего.",
          "imagePrompt": "A small tortoise with a canvas satchel lounges beside an arched trail gate, holding its familiar route map like a welcome placard. Eight footprint-shaped paving stones curve toward the gate, where its walking stick rests.",
          "fishMarkup": "[confident]Одна и та же версия программы выполнена в <emphasis>8 разных дней</emphasis> — ты возвращаешься к знакомому маршруту. [playful]Карта уже встречает тебя как своего.",
          "audioText": "Одна и та же версия программы выполнена в 8 разных дней — ты возвращаешься к знакомому маршруту. Карта уже встречает тебя как своего."
        },
        {
          "id": "plan.repeat_program:t3",
          "title": "Навигатор для маршрута",
          "phrase": "Ты выполнил одну и ту же версию программы в 20 разных дней. Теперь маршрут сам спрашивает у тебя дорогу.",
          "imagePrompt": "A small tortoise with a canvas satchel runs a tiny directions desk beneath an arched trail gate, spreading its familiar map across the counter. A winding ribbon of road with little arms leans forward and shrugs helplessly, seeking guidance.",
          "fishMarkup": "[triumphant]Ты выполнил одну и ту же версию программы в <emphasis>20 разных дней</emphasis>. <slow>Теперь</slow> [playful]маршрут сам спрашивает у тебя дорогу.",
          "audioText": "Ты выполнил одну и ту же версию программы в 20 разных дней. Теперь маршрут сам спрашивает у тебя дорогу."
        }
      ]
    },
    {
      "id": "plan.chapters",
      "tiers": [
        {
          "id": "plan.chapters:t1",
          "title": "Два тома движения",
          "phrase": "Ты выполнил исходные планы 2 разных шаблонов программы. Библиотека тренировок открыта — шептать не обязательно!",
          "imagePrompt": "A cheerful beaver librarian in a pocketed waistcoat opens two chunky workout binders on a low reading desk. Their pages show distinct exercise diagrams, and the beaver holds its paws wide to welcome the first visitors.",
          "fishMarkup": "[warm]Ты выполнил исходные планы <emphasis>2 разных шаблонов программы</emphasis>. [playful]Библиотека тренировок открыта — шептать не обязательно!",
          "audioText": "Ты выполнил исходные планы 2 разных шаблонов программы. Библиотека тренировок открыта — шептать не обязательно!"
        },
        {
          "id": "plan.chapters:t2",
          "title": "Тележка новых глав",
          "phrase": "Уже 4 разных шаблона программы: ты выполнил их исходные планы. Бобр-библиотекарь везёт пополнение на тележке.",
          "imagePrompt": "A beaver librarian in a pocketed waistcoat proudly pushes a compact library trolley carrying four thick workout binders with distinct exercise diagrams. Its broad tail steadies the rear wheel as it rounds a reading desk.",
          "fishMarkup": "[confident]Уже <emphasis>4 разных шаблона программы</emphasis>: ты выполнил их исходные планы. [playful]Бобр-библиотекарь везёт пополнение на тележке.",
          "audioText": "Уже 4 разных шаблона программы: ты выполнил их исходные планы. Бобр-библиотекарь везёт пополнение на тележке."
        },
        {
          "id": "plan.chapters:t3",
          "title": "Гантель с читательским билетом",
          "phrase": "Ты выполнил исходные планы 6 разных шаблонов программы. Даже гантель пришла к тебе за читательским билетом.",
          "imagePrompt": "A beaver librarian in a pocketed waistcoat sits behind a desk built from six chunky workout binders. It hands a blank library card to an eager anthropomorphic dumbbell, which stands on tiptoe and carries a tiny book bag.",
          "fishMarkup": "[triumphant]Ты выполнил исходные планы <emphasis>6 разных шаблонов программы</emphasis>. <slow>Даже гантель</slow> [playful]пришла к тебе за читательским билетом.",
          "audioText": "Ты выполнил исходные планы 6 разных шаблонов программы. Даже гантель пришла к тебе за читательским билетом."
        }
      ]
    }
  ]
